function parseThresholds(thresholdStrings?: string[]) {
  const thresholds: Record<string, number> = {};
  if (!thresholdStrings) return thresholds;

  for (const thresholdStr of thresholdStrings) {
    const [metricId, minStr] = thresholdStr.split('=');
    if (!metricId || !minStr) {
      throw new Error(`Invalid threshold format: "${thresholdStr}". Expected format: <metric>=<number>`);
    }
    const minValue = Number.parseFloat(minStr);
    if (Number.isNaN(minValue) || minValue < 0 || minValue > 1) {
      throw new Error(`Invalid threshold value for ${metricId}: "${minStr}" must be a number between 0 and 1`);
    }
    thresholds[metricId] = minValue;
  }
  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let thresholds: Record<string, number> | undefined;
  if (options.threshold?.length) {
    thresholds = parseThresholds(options.threshold);
    const validateThresholds = (Eval.validateThresholds as unknown as (config: unknown) => any);
    const validation = validateThresholds(thresholds, evaluations);
    if (!validation.valid) {
      log.error('Invalid threshold configuration');
      validation.errors.forEach((error: string) => {
        console.error(` - ${error}`);
      });
      process.exit(2);
    }
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (report.thresholds && report.thresholds.length > 0 && !report.passed) {
    process.exit(1);
  }
}

