import {
  generateReport,
  loadDataset,
  runEvaluations,
  writeReport,
  validateThresholds,
  evaluateThresholds
} from './index.js';

const tmpDirs = [];
afterEach(() => {
  while (tmpDirs.length) {
    fs.rmSync(tmpDirs.pop(), { recursive: true, force: true });
  }
});

